// Фильтруем новости, опубликованные за последние N часов
const hours = 3;

const moscowOffset = 3 * 60 * 60 * 1000;

const now = new Date(Date.now() + moscowOffset);
const cutoff = new Date(now.getTime() - hours * 60 * 60 * 1000);

const filtered = items.filter(item => {
  const src = item.json;

  const dateStr =
    src.pubDate ||
    src.published ||
    src.updated ||
    src["dc:date"] ||
    src.date ||
    null;

  if (!dateStr) return false;

  const pub = new Date(dateStr);
  if (isNaN(pub)) return false;

  pub.setTime(pub.getTime() + moscowOffset);

  return pub >= cutoff && pub <= now;
});

// Подготовка текста для LLM
for (const item of filtered) {

  // Очистка HTML
  if (item.json.contentSnippet) {
    item.json.contentSnippet = item.json.contentSnippet
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/\s+/g, " ")
      .trim();
  }

  // Если нет contentSnippet — используем content
  if (!item.json.contentSnippet && item.json.content) {
    item.json.contentSnippet = item.json.content
      .replace(/<[^>]*>/g, " ")
      .replace(/\s+/g, " ")
      .trim();
  }

}

return filtered;

// Чтобы понимать, откуда пришла новость.
// После каждого RSS Trigger добавляем маленькую Code-ноду.

for (const item of items) {
  item.json.source = "BBC Sport";
}
return items;

